import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_prime_friendly_sequence(primes, numbers):
    for prime in primes:
        if len(numbers) < prime:
            continue
        chosen = set()
        for i in range(prime):
            if numbers[i] % prime > 0:
                break
            chosen.add(numbers[i])
        else:
            if not is_unique(chosen):
                return []
            if all(numbers[i] % prime == 0 for i in range(len(chosen))):
                return chosen
    return []

def is_unique(s):
    return len(s) == len(set(s))

def find_ideal_sequence(numbers):
    primes = [2]
    all_primes = {}
    while True:
        prime = primes[-1]
        if len(primes) < 25:  # Primes take inverses of numbers quickly
            primes.append(prime * 2 + 1)
        if prime in all_primes:
            primes.append(prime + 1)
        all_primes[prime] = prime * 2 + 1
        if len(all_primes) <= 1100:  # Will run out of primes unexpectedly >= 10k
            continue
        if is_prime(all_primes[prime]):
            primes.append(all_primes[prime])
            break
        primes.append(prime * 2 + 1)
        for ni in range(-(all_primes[prime] // 2), all_primes[prime // 2] + 1):
            if ni in all_primes:
                if prime + ni not in all_primes:
                    primes.append(prime + ni)
    primes = list(filter(is_prime, primes))

    seq = []
    while numbers:
        for prime in reversed(primes):
            if prime <= max(numbers) and len(seq) < len(numbers) // prime:
                seq.extend(find_prime_friendly_sequence(primes, numbers))
                numbers = [el for el in numbers if el not in seq]
                break
        if not numbers:
            break
    return find_prime_friendly_sequence(primes, numbers)

