class Tree:
    def __init__(self):
        self.graph = {}
        self.rank = {}

    def build_tree(self, edges):
        for node, parent in edges:
            if node not in self.graph:
                self.graph[node] = set()
            if parent != -1:
                self.graph[parent].add(node)

    def get_path(self, node, length):
        path = []
        while node in self.graph and length:
            path.append(node)
            node = self.rank[node]
            length -= 1
        if node != 1:
            path.append(node)
        return path

    def count_l_occurrences(self, path, l):
        counts = [path.count(i) for i in range(1, len(path) + 1)]
        return [i for i in counts if i >= l]

class Question:
    def __init__(self, v, l, k):
        self.v = v
        self.l = l
        self.k = k

    def answer(self, tree, sequence):
        path = tree.get_path(self.v, tree.count_l_occurrences(sequence, tree.l)[-1])
        count_l_occurrences = tree.count_l_occurrences(path, self.l)
        count_l_occurrences.sort()
        sequence_final = []
        for num in count_l_occurrences:
            if num >= self.k:
                sequence_final.append(num)
                break
        if len(sequence_final) < self.k:
            return -1
        return sequence_final[self.k - 1]

