import sys
from collections import defaultdict

def read_input():
    n, m, p = map(int, input().split())
    return n, m, p

def reconstruct_graph(edges, n):
    graph = defaultdict(set)
    for u, v in edges:
        graph[u].add(v)
    return graph

def bellman_ford(graph, source, num_vertices, p):
    distances = [0] + [sys.maxsize] * (num_vertices - 1)
    distances[source] = 0
    for _ in range(num_vertices - 1):
        for u in range(1, num_vertices):
            for v in graph[u]:
                if distances[v] > distances[u] + graph[u][v]:
                    distances[v] = distances[u] + graph[u][v]
    return distances

def find_differences(distances, input_graph):
    differences = defaultdict(int)
    for u in range(1, len(input_graph)):
        for v in range(1, len(input_graph)):
            if distances[u] + input_graph[u][v] < distances[v]:
                differences[(u, v)] -= 1
            if distances[u] + input_graph[u][v] > distances[v]:
                differences[(v, u)] += 1
    return differences

def solve(epogetti_position=_input_generator, n=_input_generator, p=_input_generator):
    source, m, p = read_input()
    input_graph = reconstruct_graph(m, n)
    graph = {}
    for u, v in input_graph:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = p % p
        graph[v][u] = p % p
    distances = bellman_ford(graph, source, n, p)
    differences = find_differences(distances, input_graph)
    solution = sum(differences.values()) % (p - 1)
    return solution * solution % p

