from typing import List
from collections import defaultdict

def is_square_subset(rectangles: List[tuple]) -> bool:
    # Use sets to store the corners of the rectangles
    edges = defaultdict(set)
    for x1, y1, x2, y2 in rectangles:
        edges[(x1, y1)].add(x2)
        edges[(x1, y2)].add(x2)
        edges[(x2, y1)].add(x1)
        edges[(x2, y2)].add(x1)

    # Sort edges by y-coordinate to ensure they are continuous
    sorted_edges = sorted(edges.items(), key=lambda x: x[0][1])

    # Use a set to store the unique edges
    unique_edges = set()
    previous_y = -1
    for edge, new_vertices in sorted_edges:
        if edge[1] != previous_y:
            previous_y = edge[1]
            unique_edges.add(edge)

    # If the number of unique edges is less than 3, it means there's a 2x2 square
    if len(unique_edges) < 3:
        return True

    # Remove horizontal and vertical edges that form a square
    horizontal_edges = [edge for edge in sorted_edges if edge[0][1] == new_vertices]
    vertical_edges = [edge for edge in sorted_edges if edge[0][0] == new_vertices]

    horizontal_unique_edges = set()
    for edge_y, new_vertices_y in sorted_edges:
        if edge_y[1] != previous_y:
            previous_y = edge_y[1]
            horizontal_unique_edges.add((edge_y[0], new_vertices_y))

    vertical_unique_edges = [edge for edge in sorted_edges if edge[0][0] == new_vertices]

    # Check both sets of edges to ensure they form a 2x2 square
    for edge in horizontal_unique_edges:
        if len(edges[edge]) != 2:
            continue
        x2, y1 = min(edge), min(new_vertices)
        x2, y2 = max(edge), min(new_vertices)
        if not all(x in edges[(x2, y1)] and x in edges[(x2, y2)] for x in new_vertices):
            continue
        for x in sorted(new_vertices)[:-1]:
            if x not in edges[(x2, y1)] or sorted(new_vertices)[-1] not in edges[(x2, y2)]:
                break
        else:
            for x in sorted(new_vertices, reverse=True):
                if not (x in edges[(x2, y1)] and x in edges[(x2, y2)]):
                    break
            else:
                continue
        return True

    for edge in vertical_unique_edges:
        if len(edges[edge]) != 2:
            continue
        x1, y2 = min(edge), min(new_vertices)
        x2, y1 = max(edge), min(new_vertices)
        if not all(y in edges[(x1, y)] and y in edges[(x2, y)] for y in new_vertices):
            continue
        for y in sorted(new_vertices)[:-1]:
            if not any(y in edges[(x1, y)] and sorted(new_vertices)[-1] in edges[(x2, y)]):
                break
        else:
            for y in sorted(new_vertices, reverse=True):
                if not (any(y in edges[(x1, y)] and sorted(new_vertices)[-1] in edges[(x2, y)])):
                    break
            else:
                continue
        return True

    return False

