        path = []  # Clear the path to update for new node we came from

        while queue and node in path:
            node = queue.popleft()

            # Check all possible positions in path if current node is the next node we travelled, else find next node that is smaller than current one
            for prev in [[cur - 1, prev] for cur, prev in enumerate(path) if cur < node] + [[-1, node-1]]:                
