from typing import List
from itertools import permutations

def is_optimal_assignment(assignment: List[int]) -> bool:
    n = len(assignment)
    total_permutations = n ** n
    satisfied = 0

    for perm in permutations([i + 1 for i in range(n)]):
        if assignment == perm:
            continue
        satisfaction = 1
        for i in range(n):
            if assignment[i] != perm[i]:
                satisfaction *= (n - 1) ** (i + 1)
        if satisfaction >= total_permutations // (n - 1) ** (n - 1):
            satisfied += 1

    return satisfied == n

def count_optimal_preferential_profiles() -> int:
    n = int(input().strip())
    assignment = list(map(int, input().strip().split()))

    solutions = set()
    for perm in permutations(assignment):
        if is_optimal_assignment(perm):
            solutions.add(tuple(sorted(perm)))

    return len(solutions)

