        adj[p].append(i)
    return adj, parents

def dfs(node, parent, edges, current_desc):
    last_index = -1
    for child in edges[node]:
        if child == parent:
            continue
        current_desc[child][0] = child
        current_desc[child].append(current_desc[node][0])
        last_index = len(current_desc[child])
        dfs(child, node, edges, current_desc)

def solve(current_desc, edges, parent, l, cur_idx):
    q = current_desc[parent][last_index] if parent else 0
    if l <= q and 0 <= cur_idx - q - 1 <= len(current_desc[parent]) - 1 - q:
        return current_desc[parent][cur_idx - q - 1]
    if q < l:
        return -1
    current_desc[parent].remove(q)
    current_desc[parent].append(q)
    dfs(parent, parent, edges, current_desc)
    return solve(current_desc, edges, parent, l, cur_idx)

if __name__ == "__main__":
