from math import gcd

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def modulo_inverse(e, m):
    g, x, y = extended_gcd(e, m)
    if g != 1:
        raise Exception('No modular inverse')
    return x % m

def reduce_to_smallest_multiple(q, a, m):
    lcm = q * m
    a %= lcm
    count = m // q
    return a, (a - count * q) % lcm

def count_tuples(n, primes):
    result = 1
    lcm = 1
    for p in primes:
        a, diff = reduce_to_smallest_multiple(p, 0, p)
        factor = p * (p - 1) // 2
        result *= pow(a * factor - 1, factor, p)
        lcm *= p if diff == 0 else diff
    return reduce_to_smallest_multiple(lcm, result, primes[-1])

def process_input(n):
    if n == 1:
        return (1, 1, 0)
    primes = [int(x) for x in input().split()]
    return count_tuples(n, primes)

