def check_fourth_elements(sequence):
    for i in range(1, len(sequence)):
        for j in range(i + 1, len(sequence)):
            if sequence[i] == sequence[j]:
                return False
            diff = abs(sequence[i] - sequence[j])
            if diff % 2 == 1:
                return False
    return True

