from typing import List

def maximize_beauty(n: int, m: int) -> List[List[int]]:
    if m == 0:
        # if no matches have been played yet, return the maximum possible beauty
        return ['1'] * n

    results = [['0'] * n for _ in range(n)]
    remaining_matches = n * (n - 1) // 2 - m

    if remaining_matches == 0:
        return results[:]

    if remaining_matches % 2 == 0:
        # If an odd number of matches remain, we can't ensure a perfect beauty since there's an imbalance in the outcomes
        return ' '.join(results)

    # If an even number of matches remain, we start from best worst possible, everything the rest is 0 most beautiful
    best_worst = 0
    best_index = -1
    for i in range(n):
        for j in range(i + 1, n):
            if results[i][j] == '1':
                if remaining_matches % 2 == 0:
                    continue
                best_worst += 1
                break
        if best_worst > 1:
            best_index = i
            break

    for i in range(n):
        results[i][best_index] = '0'

    return results


