            if self.inverse_table[i] == 0:
                self.inverse_table[i] = (self.mod - self.inverse_table[self.mod // i]) % self.mod
                self.solutions.append(i)

    def solve_equation(self, coefficients):
        solutions = []
        for a in coefficients:
