        return a * self.inverse_table[b] % self.mod

    def modular_inverse(self, a, b):
        return pow((a % self.mod), self.mod - 2, self.mod)

    def modular_congruence(self, a, b):
        return (a * self.modular_inverse(b, self.mod) + self.mod) % self.mod

    def conserved_prob(self, X):
        return pow(len(self.solutions), len(X), self.mod)

