def color_graph(graph):
    coloring = {}
    for node in graph:
        for neighbor in graph[node]:
            if node not in coloring:
                coloring[node] = 'A'
            if neighbor not in coloring:
                coloring[neighbor] = 'B'
            while coloring[neighbor] != 'B':
                coloring[neighbor] = 'G'
            coloring[node] = 'B'
        for _neigh in graph[node]:
            if node != _neigh:
                while coloring[_neigh] == 'B':
                    coloring[_neigh] = 'G'
    return coloring

def magic_coins(n, graph, coloring, bottleneck):
    if n not in bottleneck:
        bottleneck[n] = len(coloring[n])
    edges = defaultdict(int)
    for i, (a, b) in enumerate(graph):
        if a == n:
            for _neighbor in graph[b]:
                if _neighbor:
                    if coloring[b] != coloring[_neighbor]:
                        edges[a] += 2 ** (coloring[b] - coloring[_neighbor])
        if b == n:
