                        dist_max += non_increasing_path_distance(ind)
                    elif num_nodes[frozenset((ind-1, first, 0))]:
                        first = ind - 1
                    else:
                        dist_min += -1
            elif i > 1:
                for ind in range(1, N+1):
                    if num_nodes[frozenset((1, ind, 0))]:
                        dist_min += non_increasing_path_distance(ind)
                    elif num_nodes[frozenset((ind-1, first, 0))]:
                        first = ind - 1

            else:
