                    dist_min += non_increasing_path_distance(num)
                    dist_max += non_increasing_path_distance(num)
            if dist_min - s[1] < dist_max - s[1]:
                continue
            if result < s[1] - dist_min:
                result = s[1] - dist_min

    return s[1] - result

