        for opponent in opponent_count:
            if opponent not in can_beat:
                possible_winners |= opponent_count[opponent]
        possible_winners.update(enemy for _, enemy in can_beat[opponent] if opponent not in possible_winners)
        unique_winners = list(possible_winners)
