from collections import defaultdict

def shortest_path_tree(node, parent_tree):
    path = [node]
    while node != 1:
        for neighbor in parent_tree[node]:
            if neighbor not in path:
                path.append(neighbor)
                yield path
                node = neighbor
                break
        else:
            node = parent_tree[node][0]

def count_odd_ones(node, parent_tree, count):
    values = set()
    for path in shortest_path_tree(node, parent_tree):
        for i, value in enumerate(path, start=1):
            if i < count:
                if count > 1:
                    values.add(value)
                else:
                    values = {value}
    return values

