from typing import List

def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_friendly(primes: List[int], sequence: List[int]) -> bool:
    """Check if a sequence of primes is friendly."""
    from itertools import combinations
    for p in combinations(primes, len(sequence)):
        valid = True
        for i, x in enumerate(sequence):
            if x % p[i] != 0:
                valid = False
                break
        if valid:
            return True
    return False

def find_ideal_sequence(n: int, k: int, x: List[int]) -> List[int]:
    """Find the ideal sequence from the given integers."""
    primes = [i for i in x if is_prime(i)]
    possible_sequences = []
    for i in range(len(x)):
        temp = x[i:]
        temp.remove(x[i])
        for j in range(len(temp)):
            subsequences = tuple(sorted(tuple(sorted(subsequence)) for subsequence in combinations(temp, i)))
            if len(subsequences) > 0 and subsequences not in possible_sequences:
                possible_sequences += subsequences
    for sequence in possible_sequences:
        if is_friendly(primes, tuple(sorted(sequence))):
            return sorted(sequence)
    return []

