from collections import defaultdict

class Tree:
    def __init__(self, n, parent):
        self.n = n
        self.parent = parent
        self.clipped_edges = []

        self.children = [[] for _ in range(n)]
        for i in range(1, n):
            self.children[parent[i]].append(i)

        self.graph = [[] for _ in range(n)]
        for i in range(1, n):
            for j in self.children[i]:
                if j in self.parent:
                    self.graph[i].append(j)
                else:
                    self.graph[j].append(i)

        self.price = [-1] * n
        self.santa_flavors = [defaultdict(int) for _ in range(n)]
        for i in range(1, n):
            self.santa_flavors[i][parent[i]] = self.santa_flavors[self.parent[i]][i]

    def update_cost(self, index, flavor, cost):
        if self.price[index] != -1:
            return

        neighbors = self.graph[index]
        self.price[index] = cost
        for neighbor in neighbors:
            self.update_cost(neighbor, flavor, cost)

    def find_melted_cost(self, index, flavor, c_k):
        if self.price[index] == -1:
            return 0

        for child in self.graph[index]:
            if child != self.parent[index]:
                if self.price[child] == -1:
                    continue

                p_c_k = (self.santa_flavors[index][child] - self.santa_flavors[index][flavor]) ** 2
                self.clipped_edges.append((p_c_k, self.price[child] - self.price[index], 0, child))

        total_cost = self.price[index]
        if self.price[index] == c_k + 1 or self.price[index] == c_k - 1:
            total_cost = self.price[index]

        return total_cost

    def find_price(self, flavor):
        if self.price[0] == c_k:
            return 0

        tree = self
        total_cost = tree.price[0]
        punctual_cost = 0

        heap_cost = [(0, 0, punctual_cost, 0, 0)]
        while heap_cost:
            cap_cost, cap_index, punctual_cost, c_k1, flavor1 = heappop(heap_cost)
            cap_cost += self.price[cap_index]

            for neighbor in tree.graph[cap_index]:
                if neighbor != tree.parent[cap_index] and self.price[neighbor] == -1:
                    heappush(heap_cost, (cap_cost, neighbor, punctual_cost, self.price[neighbor], flavor1))
                else:
                    total_cost += (cap_cost - self.price[cap_index]) ** 2
                    punctual_cost += count(prestem_index)

        expected_error = pow(total_cost - punctual_cost, 2)

        return expected_error


