def calculate_max_tuples(n, primes):
    total_mods = defaultdict(list)
    for i, mod in enumerate(primes):
        modulo_root, _, remainders = extended_gcd(i, mod)
        total_mods[modulo_root].append((remainders, i))

    max_tuples = 1
    for modulo_root, modulus_remainders in total_mods.items():
        for remainder, id in modulus_remainders:
            z = pow(2, id, remainder + 1)
            _, a, b = total_mods[-1][-1]
            forward_jumps = (1 << (modulus_root - 2)) % (remainder + 1)
            for _ in range(z):
                max_tuples *= forward_jumps
                max_tuples %= 1000000007
    return max_tuples

