from collections import deque

def find_min_time(N, edges, colors):
    graph = [[] for _ in range(N)]
    for start, end in edges:
        graph[start - 1].append(end - 1)
        graph[end - 1].append(start - 1)

    time = float('inf')
    pq = deque([(0, [0] * N)])  # (time_seen, colors)
    visited = [False] * N

    while pq:
        t, colors = pq.popleft()
        if visited == [True] * N or t >= time:
            if all(colors):
                time = t
                break
            else:
                if colors[0] != 0:
                    colors[0] *= -1
                else:
                    time = min(time, t + 1)
                    colors[0] = 1

        for i, color in enumerate(colors):
            if not visited[i]:
                visited[i] = True
                for e in graph[i]:
                    if color > 0:
                        colors[e] *= -1
                    else:
                        colors[e] = 1
                    pq.append((t + 1, colors[:]))
                colors[i] = 1

    return time

