def max_championship_games(n, k, teams_fans):
    def get_new_teams(games):
        new_teams = set()
        for i in range(len(games)):
            for j in range(i + 1, len(games)):
                if games[i] not in new_teams and games[j] not in new_teams:
                    new_teams.add(games[i])
                    new_teams.add(games[j])
        return new_teams

    best_games = 0
    for i in range(n, 2 * n):
        possible_games = set(range(2**i))
        for x in range(1, 2**i + 1):
            for y in range(x + 1, 2**i + 1):
                possible_games.remove(x)
                possible_games.remove(y)
        to_keep = [x for x in possible_games if k >= len(possible_games - set(x))]
        best_games += len(to_keep) + len(possible_games - set(to_keep))
    best_games += len(teams_fans) * (k - 1)
    return max(best_games, 0)

