def find_max_games(n, k, fans):
    if n == 0:
        return 0

    if n == 1:
        return k

    if n == 2:
        if k == 1:
            return 2
        elif k == 2:
            return 4
        else:
            return 2

    fans.sort(reverse=True)
    second_most_fan = fans[1]

    if n % 2 == 1:
        most_fan = fans[0]
        previous_coordinate = 1
    else:
        most_fan = fans[1]
        previous_coordinate = -1

    for coordinate in range(n // 2 + 1):
        num_games = 2 ** (coordinate + previous_coordinate)
        if most_fan == fans[coordinate]:
            if last_fan == fans[last]:
                num_games *= 2 ** (coordinate + previous_coordinate + 1)
            else:
                num_games *= 2 ** (coordinate + previous_coordinate + 1) * 2
        elif last_fan == fans[coordinate] and last_coordinate != coordinate:
            num_games *= 2 ** (previous_coordinate + 1)
            last_fan = fans[last]

        last_coordinate = coordinate + previous_coordinate

        if num_games > n:
            break

    if n % 2 == 1:
        num_games *= 2
        previous_coordinate = 1

    fans.sort(reverse=True)
    fan_counter = 0
    like_fans = []

    for coordinate in range(n // 2 + 1):
        like_fans.append(fans[fan_counter])
        fan_counter += 1

    for i in range(n // 2):
        like_fans.sort(reverse=True)
        for j in range(len(like_fans) - 1):
            if abs(fans[j + 1] - likes_fans[j]) < n // 2:
                if like_fans[j] == like_fans[j + 1]:
                    if last_fan == like_fans[j]:
                        num_games *= 2 ** (1 - old)
                    else:
                        num_games *= 2 ** (previous_coordinate + 1)
                num_games *= 2

        # calculate games with all coordinates checked previously
        goToLower = n // 2
        for i in range(goToLower):
            last_fan = fans[fan_counter]
            fans.extend(like_fans[:])
            liking = like_fans[:]
            like_fans.clear()
            fans.sort()
            old = previous_coordinate
            previous_coordinate = -1
            like_fans.clear()
            num_games *= 2
            new = num_games + goToLower
        goToLower = 2 ** (coordinate + previous_coordinate)
        previous_coordinate = previous_coordinate

    return num_games

