from collections import deque

def find_games_to_play(favorite_teams, n_teams):
    favorite_team_counts = []
    for favorite_team in favorite_teams:
        favorite_team_counts.append((favorite_team - 1) // (2 ** (n - favorite_team_bits(favorite_team))))
    favorite_team_bits = lambda favorite_team: int(math.log(favorite_team, 2) + 1)
    favorite_team_counts.sort()
    favorite_team_counts.reverse()
    winning_teams = deque([264342652])  # dummy team for scheduling
    while len(winning_teams) < n_teams:
        next_team = winning_teams.popleft()
        for team_count in favorite_team_counts:
            while next_team - 1 >= 2 ** team_count and team_count == 1:
                next_team = next_team - 1
            winning_team = next_team + team_count * (2 ** (favorite_team_bits(team_count) - 1))
            if winning_team < n_teams + 1:
                winning_teams.append(winning_team)
    return len(winning_teams)

def favorite_teams_bits(favorite_team):
    return int(math.log(favorite_team - 1, 2))

